"""Write app/coco_classes.py from torchvision's weight metadata (no download needed)."""
from pathlib import Path

from torchvision.models.detection import RetinaNet_ResNet50_FPN_Weights

OUT = Path(__file__).resolve().parent.parent / "app" / "coco_classes.py"


def main() -> None:
    categories = RetinaNet_ResNet50_FPN_Weights.COCO_V1.meta["categories"]
    used = {i: name for i, name in enumerate(categories) if name not in ("__background__", "N/A")}
    lines = [
        '"""GENERATED by scripts/generate_coco_classes.py from torchvision weight metadata. Do not edit."""',
        "",
        "COCO_CATEGORIES: dict[int, str] = {",
        *[f"    {i}: {name!r}," for i, name in used.items()],
        "}",
        "",
    ]
    OUT.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {OUT} ({len(used)} classes)")


if __name__ == "__main__":
    main()
